for C in [bool,int,float,complex,str,list,tuple,dict,range,slice,set,frozenset,bytes,bytearray,memoryview,property,staticmethod,classmethod,super,type,object,Exception,ValueError]:
 a=type.mro(C)
 print(a==list(C.__mro__),a[0] is C)

class C:
 mro=staticmethod(lambda: [7])
print(C.mro()==[7],type.mro(C)==[C,object])

class M(type):
 def __getattribute__(cls,name):
  print(name)
  return type.__getattribute__(cls,name)
class C(metaclass=M): pass
print(C.mro()[0] is C)

class C:
 @property
 def __class__(self):
  print("unexpected")
  return type
type.mro(C())

class M(type):
 def __getattribute__(cls,name):
  raise ValueError("original")
class C(metaclass=M): pass
C.mro()

class M(type):
 def __getattribute__(cls,name):
  print(name)
  return 7
class C(metaclass=M): pass
print(C.__base__,type.__getattribute__(C,"__base__") is object)

class M(type):
 print("body")
 def mro(cls): return type.mro(cls)
class C(metaclass=M): pass
print(C.__name__)

class M(type):
 def __getattribute__(cls,name):
  print(name)
  return type.__getattribute__(cls,name)
class C(metaclass=M): pass
print(type.mro.__get__(C).__qualname__)
